describe('Date Picker Validation', () => {
    beforeEach(() => {
        cy.visit('/booking'); // Replace with the actual URL of the booking page
    });

    it('should allow selecting a future date', () => {
        const futureDate = Cypress.moment().add(1, 'days').format('YYYY-MM-DD');
        cy.get('input[type="date"]').type(futureDate);
        cy.get('form').submit();
        cy.get('.success-message').should('be.visible').and('contain', 'Booking confirmed for ' + futureDate);
    });

    it('should prevent selecting a past date', () => {
        const pastDate = Cypress.moment().subtract(1, 'days').format('YYYY-MM-DD');
        cy.get('input[type="date"]').type(pastDate);
        cy.get('form').submit();
        cy.get('.error-message').should('be.visible').and('contain', 'Please select a valid date in the future');
    });
});
